/**
 * AI features across every module. Each one has an honest non-AI fallback, and every result says
 * which it is: "ai" (generated by the configured model) or "automatic" (rules and approved content,
 * no AI). Nothing here takes a decision: outputs are drafts, suggestions or explanations for a person.
 */

export type AiMode = "ai" | "automatic";
export type AiOutcome<T> = { mode: AiMode; result: T; notice?: string };

export async function withFallback<T>(ai: () => Promise<T>, fallback: () => T | Promise<T>): Promise<AiOutcome<T>> {
  if (!aiConfigured()) {
    return { mode: "automatic", result: await fallback(), notice: "AI is not switched on for this deployment, so this was produced automatically from approved content and records (not AI)." };
  }
  try {
    return { mode: "ai", result: await ai() };
  } catch (e) {
    if (!(e instanceof AiUnavailable)) throw e;
    return { mode: "automatic", result: await fallback(), notice: `${e.message} Showing an automatic version instead (not AI).` };
  }
}

const NO_DECISIONS =
  "You never make or recommend decisions about admissions, discipline, welfare or a child's safety; for those, say a member of staff must decide. Never invent figures, names, dates, fees or policies.";

// ─── AI Copilot (every role) ────────────────────────────────────────────────

export async function copilotReply(input: {
  userKey: string; role: Role; firstName: string; facts: Fact[]; help: Passage[]; pages: string[]; messages: ChatMessage[];
}) {
  const system = `${SCHOOL_CONTEXT}
You are the VoxVision School OS Copilot for ${input.firstName}, signed in as: ${ROLE_LABELS[input.role]}.
You help them understand their work in the system and find their way around it.
Use ONLY two sources: (1) the live facts below, which are everything this user is allowed to see right now, and (2) the user-guide excerpts. If the answer is not in them, say you cannot see that information and suggest where in the app to look or whom to ask.
${NO_DECISIONS}
${input.role === "student" || input.role === "parent" ? "The user may be a child: be warm, simple and encouraging. If anything suggests worry, unsafety or harm, tell them to speak to a teacher, the warden or a parent, and mention CHILDLINE 1098." : "Be concise and practical, like a capable colleague."}
Format: short Markdown (a few sentences or bullets, under 180 words). When you point to a page, use ONLY these menu names, exactly as written (they are the pages this user can open): ${input.pages.map((p) => `"${p}"`).join(", ")}. Never mention any other page.
Reply in the language the user writes in (English or Hindi).

<live_facts as_of="now">
${factsAsText(input.facts) || "- (no facts available)"}
</live_facts>

<user_guide_excerpts>
${formatPassages(input.help) || "(none matched)"}
</user_guide_excerpts>`;
  return generate({ userKey: input.userKey, system, messages: input.messages, effort: "low", maxTokens: 1500 });
}

export async function briefingReply(input: { userKey: string; role: Role; firstName: string; facts: Fact[]; pages: string[] }) {
  const system = `${SCHOOL_CONTEXT}
You write a short daily briefing for ${input.firstName} (${ROLE_LABELS[input.role]}) from the facts provided, and nothing else.
Start with one sentence summarising the day. Then 3 to 5 bullets, most important first, each with a concrete next step and the page to use. Name pages ONLY with these menu names, exactly as written: ${input.pages.map((p) => `"${p}"`).join(", ")}.
${NO_DECISIONS}
Plain, warm, professional English. Under 140 words. Markdown bullets.`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: `Facts:\n${factsAsText(input.facts)}` }], effort: "low", maxTokens: 1200 });
}

/** Rule-based briefing used when AI is off: the facts themselves, attention items first. */
export function automaticBriefing(facts: Fact[]) {
  const ordered = [...facts].sort((a, b) => (a.tone === "attention" ? 0 : 1) - (b.tone === "attention" ? 0 : 1));
  const attention = facts.filter((f) => f.tone === "attention").length;
  return `${attention ? `${attention} item${attention > 1 ? "s need" : " needs"} attention today.` : "Nothing urgent today."}\n\n${ordered.map((f) => `- ${f.text}`).join("\n")}`;
}

// ─── AI Study Assistant (students) ──────────────────────────────────────────

export const STUDY_MODES = {
  chat: "Ask anything",
  simplify: "Explain simply",
  steps: "Step by step",
  notes: "Revision notes",
  flashcards: "Flashcards",
  quiz: "Quiz me",
} as const;
export type StudyMode = keyof typeof STUDY_MODES;

function studySystem(topic: { subject: string; name: string; level: number }, passages: Passage[], extra: string) {
  return `${SCHOOL_CONTEXT}
You are a patient AI study assistant for a Class ${topic.level} student studying ${topic.subject}: "${topic.name}".
Rules:
- Teach only from the teacher-approved sources below. If they do not cover something, say so and suggest asking the teacher. Do not invent facts.
- Help the student understand; for homework-style questions guide them through the method rather than only giving the final answer.
- Stay on school learning. Politely decline anything unrelated, unsafe or personal. Never ask for personal information.
- Use simple language for the student's age, short paragraphs and Markdown. Reply in the student's language (English or Hindi).
${extra}

<approved_sources>
${formatPassages(passages) || "(no approved material yet)"}
</approved_sources>`;
}

const STUDY_INSTRUCTIONS: Record<Exclude<StudyMode, "flashcards">, string> = {
  chat: "Answer the student's latest message in under 220 words. End with one short question that checks their understanding.",
  simplify: "Explain the student's question (or, if there is none, the topic's main idea) as simply as possible, with an everyday Indian example. Under 150 words.",
  steps: "Break the idea or problem into numbered steps. Show one fully worked example from the sources. Under 250 words.",
  notes: "Write one-page revision notes for the whole topic: key ideas as bullets, important terms in bold, a formula or rule box if relevant, and 3 'check yourself' questions with answers at the end.",
  quiz: "Ask the student ONE new short practice question from the sources (not multiple choice). If their previous message answers your last question, first say whether it is right and explain briefly, then ask the next one. This is practice only and is not marked.",
};

export async function studyReply(input: {
  userKey: string; mode: Exclude<StudyMode, "flashcards">; topic: { subject: string; name: string; level: number }; passages: Passage[]; messages: ChatMessage[];
}) {
  return generate({
    userKey: input.userKey,
    system: studySystem(input.topic, input.passages, STUDY_INSTRUCTIONS[input.mode]),
    messages: input.messages,
    effort: input.mode === "notes" ? "medium" : "low",
    maxTokens: input.mode === "notes" ? 4000 : 2000,
  });
}

const Flashcards = z.object({ cards: z.array(z.object({ front: z.string(), back: z.string() })).min(1) });
export type Flashcard = z.infer<typeof Flashcards>["cards"][number];

export async function flashcards(input: { userKey: string; topic: { subject: string; name: string; level: number }; passages: Passage[] }) {
  const out = await generateJson(Flashcards, {
    userKey: input.userKey,
    effort: "low",
    maxTokens: 3000,
    system: studySystem(input.topic, input.passages, "Create 8 revision flashcards from the sources: a short question or term on the front, a one- or two-sentence answer on the back."),
    prompt: `Make flashcards for "${input.topic.name}".`,
  });
  return out.cards.filter((c) => c.front.trim() && c.back.trim()).slice(0, 12);
}

// ─── Explain my mistake (quiz results) ──────────────────────────────────────

export async function explainMistake(input: {
  userKey: string; level: number; topic: string; prompt: string; options: string[]; chosen: number | null; correct: number; explanation: string; passages: Passage[];
}) {
  const system = `${SCHOOL_CONTEXT}
You help a Class ${input.level} student understand a practice-quiz question they got wrong, on "${input.topic}".
Be kind and specific. In under 150 words: why their choice is not right (if they chose one), why the correct answer is right, and one tip to remember it. Use only the teacher's explanation and the approved sources. Reply in English unless the question is in Hindi.`;
  const prompt = `Question: ${input.prompt}
Options: ${input.options.map((o, i) => `${String.fromCharCode(65 + i)}. ${o}`).join("  ")}
Student chose: ${input.chosen == null ? "(no answer)" : `${String.fromCharCode(65 + input.chosen)}. ${input.options[input.chosen]}`}
Correct answer: ${String.fromCharCode(65 + input.correct)}. ${input.options[input.correct]}
Teacher's explanation: ${input.explanation || "(none)"}

Approved sources:
${formatPassages(input.passages) || "(none)"}`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: prompt }], effort: "low", maxTokens: 1200 });
}

// ─── AI coding tutor ────────────────────────────────────────────────────────

export async function codeHint(input: { userKey: string; kind: string; title: string; prompt: string; code: string; result: string; hint: string }) {
  const system = `You are a friendly coding tutor for school students (ages 11 to 17) doing a ${input.kind} challenge in VoxVision School OS.
Help them get unstuck WITHOUT giving the answer: never write the corrected line, the missing value or the solution code, even partly. Point to WHERE the problem is (for example "look at line 1"), explain any error message in plain words, and ask one guiding question that lets them discover the fix themselves.
Under 120 words, Markdown, encouraging. If the code already passes, praise it and suggest one small improvement or extension.`;
  const prompt = `Challenge: ${input.title}
Task: ${input.prompt}
Teacher's hint: ${input.hint || "(none)"}

Student's code:
\`\`\`
${input.code.slice(0, 6000)}
\`\`\`

Result of running the checks:
${input.result.slice(0, 2000) || "(not run yet)"}`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: prompt }], effort: "low", maxTokens: 1000 });
}

// ─── Teacher: material drafts and class insights ────────────────────────────

const MaterialDraft = z.object({ title: z.string(), body: z.string() });

export async function draftMaterial(input: { userKey: string; subject: string; topic: string; level: number; focus: string; passages: Passage[] }) {
  return generateJson(MaterialDraft, {
    userKey: input.userKey,
    effort: "medium",
    maxTokens: 5000,
    system: `${SCHOOL_CONTEXT}
You draft CBSE-aligned learning material for a teacher to review, edit and approve before students see it. It is a DRAFT.
Write for Class ${input.level} students: clear headings, short paragraphs, worked examples, Indian everyday contexts, and a "Key points" list at the end. Markdown. 300 to 600 words.
Be factually careful; where a fact must be checked against the textbook, mark it with "(teacher to verify)". Do not copy text from any textbook.`,
    prompt: `Draft learning material for ${input.subject}, topic "${input.topic}".${input.focus ? `\nTeacher's focus: ${input.focus}` : ""}
Existing approved material on this topic (avoid repeating it; build on it):
${formatPassages(input.passages) || "(none yet)"}`,
  });
}

export async function classInsights(input: { userKey: string; data: string }) {
  const system = `${SCHOOL_CONTEXT}
You help a teacher read practice-quiz results. From the data only:
1. **Likely misconceptions**: for the weakest questions, what the most common wrong answer suggests students believe.
2. **What to re-teach**: 2 to 4 concrete classroom actions, most valuable first.
3. **Participation**: one line on participation if it is low.
Practice quizzes are a small sample: never label or judge individual students, and say results should be confirmed in class. Markdown, under 250 words.`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: input.data }], effort: "medium", maxTokens: 2500 });
}

// ─── Administration: report-card remarks, reports, enquiries, hostel ────────

export async function draftRemark(input: { userKey: string; firstName: string; level: number; summary: string }) {
  const system = `${SCHOOL_CONTEXT}
You draft a report-card remark for a class teacher to edit and approve. It is a DRAFT: the teacher decides the final words.
Write 2 or 3 sentences (under 60 words) addressed to the family: specific strengths from the data, one area to work on phrased constructively, and encouragement. Refer to the student by first name only and do not use gendered pronouns (he, she, him, her, his).
Use only the data given. No comparisons with other students, no labels about ability, behaviour, health or family, and nothing about attendance reasons.`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: `Student: ${input.firstName}, Class ${input.level}\n${input.summary}` }], effort: "low", maxTokens: 600 });
}

/** Template remark used when AI is off: built from grades only. */
export function automaticRemark(firstName: string, subjects: { subject: string; pct: number }[]) {
  if (!subjects.length) return `${firstName}'s marks for this examination have not been entered yet.`;
  const sorted = [...subjects].sort((a, b) => b.pct - a.pct);
  const best = sorted.slice(0, 2).map((s) => s.subject).join(" and ");
  const weakest = sorted.at(-1)!;
  const avg = Math.round(subjects.reduce((n, s) => n + s.pct, 0) / subjects.length);
  return `${firstName} has done ${avg >= 75 ? "very well" : avg >= 55 ? "well" : "steady work"} in this examination, especially in ${best}. ${
    weakest.pct < 60 ? `Regular practice in ${weakest.subject} will help further.` : "Keep up the consistent effort."
  }`;
}

const ReportPick = z.object({ report: z.enum(Object.keys(REPORTS) as [ReportName, ...ReportName[]]), reason: z.string() });

export async function pickReport(input: { userKey: string; question: string }) {
  return generateJson(ReportPick, {
    userKey: input.userKey,
    effort: "low",
    maxTokens: 400,
    system: `You route a school administrator's question to ONE of these standard reports (id: title):
${Object.entries(REPORTS).map(([k, v]) => `- ${k}: ${v}`).join("\n")}
Pick the single most relevant report. "reason" is one short sentence.`,
    prompt: input.question,
  });
}

/** Keyword routing used when AI is off. */
export function keywordReport(question: string): ReportName {
  const q = question.toLowerCase();
  if (/(below|low|poor|absent|irregular).*(attend)|attend.*(below|low|poor)|85/.test(q)) return "low-attendance";
  if (/attend|present|absen/.test(q)) return "attendance-30d";
  if (/exam|mark|result|grade|subject/.test(q)) return "exam-results";
  if (/enquir|admission|lead|pipeline|parent/.test(q)) return "enquiry-pipeline";
  if (/quiz|practice|participat|learning/.test(q)) return "quiz-participation";
  return "class-strength";
}

export function reportAsText(report: Report, maxRows = 60) {
  const rows = report.rows.slice(0, maxRows).map((r) => r.map((c) => c ?? "").join(" | "));
  return `${report.title} — ${report.description}\n${report.head.join(" | ")}\n${rows.join("\n")}${report.rows.length > maxRows ? `\n(${report.rows.length - maxRows} more rows)` : ""}`;
}

export async function narrateReport(input: { userKey: string; question: string; report: Report }) {
  const system = `${SCHOOL_CONTEXT}
You explain an administrative report to school management in plain English, using ONLY the table provided.
Answer the question first in one or two sentences, then up to 4 bullets of notable patterns with the exact figures. If the table cannot answer the question, say so.
Never judge individual students; low figures are prompts for a conversation, not conclusions. Under 180 words, Markdown.`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: `Question: ${input.question || "Summarise this report."}\n\n${reportAsText(input.report)}` }], effort: "low", maxTokens: 1500 });
}

/** Rule-based summary used when AI is off. */
export function automaticReportSummary(report: Report) {
  if (!report.rows.length) return `**${report.title}** has no rows for this period.`;
  const numericCol = report.head.length - 1;
  const values = report.rows.map((r) => r[numericCol]).filter((v): v is number => typeof v === "number");
  const lines = [`**${report.title}**: ${report.rows.length} row${report.rows.length > 1 ? "s" : ""}. ${report.description}`];
  if (values.length) {
    const maxRow = report.rows.find((r) => r[numericCol] === Math.max(...values));
    const minRow = report.rows.find((r) => r[numericCol] === Math.min(...values));
    lines.push(`- Highest ${report.head[numericCol].toLowerCase()}: ${maxRow?.[0]}${maxRow && report.head.length > 3 ? ` ${maxRow[2] ?? ""}` : ""} (${Math.max(...values)})`);
    lines.push(`- Lowest ${report.head[numericCol].toLowerCase()}: ${minRow?.[0]}${minRow && report.head.length > 3 ? ` ${minRow[2] ?? ""}` : ""} (${Math.min(...values)})`);
  }
  return lines.join("\n");
}

export async function draftEnquiryReply(input: { userKey: string; lang: "en" | "hi"; enquiry: string; facts: string }) {
  const system = `${SCHOOL_CONTEXT}
You draft a reply from the school's admissions office to a parent's enquiry, for staff to edit and send themselves. It is a DRAFT and is never sent automatically.
Use ONLY the verified school facts provided; for anything else (fees, seat availability, dates, decisions) say the office will confirm. Never promise admission.
Warm, respectful, concise (under 150 words). Suggest a clear next step (for example a school visit or a call). Sign off as "Admissions Office, ${SCHOOL.name}".
Write in ${input.lang === "hi" ? "Hindi (Devanagari)" : "English"}.`;
  return generate({ userKey: input.userKey, system, messages: [{ role: "user", content: `Enquiry and history:\n${input.enquiry}\n\nVerified school facts:\n${input.facts || "(none)"}` }], effort: "low", maxTokens: 1500 });
}

const Triage = z.object({
  category: z.enum(["electrical", "plumbing", "furniture", "cleaning", "other"]),
  priority: z.enum(["low", "normal", "urgent"]),
  reason: z.string(),
});
export type TriageSuggestion = z.infer<typeof Triage>;

export async function triageMaintenance(input: { userKey: string; description: string }) {
  return generateJson(Triage, {
    userKey: input.userKey,
    effort: "low",
    maxTokens: 400,
    system: `You suggest a category and priority for a school hostel maintenance request. The warden decides; this is only a suggestion.
"urgent" only for safety risks (exposed wiring, sparks, gas, flooding, broken glass, no water for many students, locks that do not close). "low" for cosmetic issues. "reason" is one short sentence.`,
    prompt: input.description.slice(0, 1000),
  });
}

export function keywordTriage(description: string): TriageSuggestion {
  const d = description.toLowerCase();
  const category: TriageSuggestion["category"] = /wire|switch|socket|fan|light|bulb|power|spark|electric/.test(d)
    ? "electrical" : /tap|leak|water|pipe|drain|toilet|flush|geyser/.test(d)
      ? "plumbing" : /bed|chair|table|door|cupboard|almirah|window|lock|shelf/.test(d)
        ? "furniture" : /clean|dust|smell|garbage|pest|insect|rat/.test(d) ? "cleaning" : "other";
  const urgent = /spark|shock|exposed|gas|flood|fire|smoke|broken glass|no water|burst|lock.*(broken|not)/.test(d);
  return { category, priority: urgent ? "urgent" : "normal", reason: "Suggested from keywords in the description (not AI)." };
}
